def _guards(up: bool) -> None:
    if up:
        op.execute(REVIEW_FUNCTIONS)
        op.execute(OCR_FUNCTIONS)
    else:
        op.execute(LEGACY_FUNCTIONS)
        for name, table in (
            ("ocr_parent_guard", "reading_material_extraction_runs"),
            ("ocr_page_metadata", "reading_material_extraction_pages"),
            ("ocr_review_guard", "reading_material_extraction_reviews"),
            ("ocr_review_page_guard", "reading_material_extraction_review_pages"),
            ("ocr_review_consistency", "reading_material_extraction_reviews"),
            ("ocr_review_pages_consistency", "reading_material_extraction_review_pages"),
        ):
            op.execute(f"DROP TRIGGER {name} ON {table}")
        for name in (
            "ocr_parent_guard",
            "ocr_page_metadata",
            "ocr_review_guard",
            "ocr_review_page_guard",
            "ocr_review_consistency",
        ):
            op.execute(f"DROP FUNCTION {name}()")
        op.execute("DROP FUNCTION ocr_validate_review(uuid)")


def _refuse_loss() -> None:
    op.execute("""DO $$ BEGIN
      IF EXISTS (SELECT 1 FROM reading_material_extraction_runs WHERE extraction_method='ocr')
         OR EXISTS (SELECT 1 FROM reading_material_extraction_reviews)
         OR EXISTS (SELECT 1 FROM reading_material_revisions WHERE source_kind='ocr_reviewed')
      THEN RAISE EXCEPTION 'Downgrade refused: OCR history exists' USING ERRCODE='23514'; END IF;
    END $$""")
